function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 2 || strs.length > 50) return 'strs needs 2 to 50 strings.';
  for (const s of strs) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 10) return 'Each string has 1 to 10 characters.';
    if (!/^[a-z]+$/.test(s)) return 'Strings contain only lowercase English letters.';
  }
  return null;
}

