function findLUSlength(strs) {
  const isSubsequence = (small, big) => {
    let matched = 0;
    for (let k = 0; k < big.length && matched < small.length; k++) {
      if (big[k] === small[matched]) {
        matched++;
      }
    }
    return matched === small.length;
  };
  let best = -1;
  for (let i = 0; i < strs.length; i++) {
    if (strs[i].length <= best) {
      continue;
    }
    let uncommon = true;
    for (let j = 0; j < strs.length && uncommon; j++) {
      if (i !== j && isSubsequence(strs[i], strs[j])) {
        uncommon = false;
      }
    }
    if (uncommon) {
      best = strs[i].length;
    }
  }
  return best;
}

