function findLUSlength(strs) {
  // List every distinct subsequence of each string and count how many strings contain it.
  const owners = new Map();
  for (const s of strs) {
    const subs = new Set();
    for (let mask = 0; mask < 1 << s.length; mask++) {
      let sub = '';
      for (let b = 0; b < s.length; b++) if (mask & (1 << b)) sub += s[b];
      subs.add(sub);
    }
    for (const sub of subs) owners.set(sub, (owners.get(sub) || 0) + 1);
  }
  let longest = -1;
  for (const [sub, count] of owners) if (count === 1 && sub.length > longest) longest = sub.length;
  return longest;
}

