function generate(rand, size) {
  const n = size === 'large' ? 50 : 2 + Math.floor(rand() * 5);
  const maxLength = size === 'large' ? 10 : 5;
  const letters = 'abcd'.slice(0, 1 + Math.floor(rand() * 3));
  const strs = [];
  for (let i = 0; i < n; i++) {
    // Repeat an earlier string or take part of one now and then, so duplicates and contained strings are common.
    if (strs.length && rand() < 0.3) {
      const earlier = strs[Math.floor(rand() * strs.length)];
      strs.push(rand() < 0.5 || earlier.length === 1 ? earlier : earlier.split('').filter(() => rand() < 0.6).join('') || earlier[0]);
      continue;
    }
    const length = 1 + Math.floor(rand() * maxLength);
    let s = '';
    for (let k = 0; k < length; k++) s += letters[Math.floor(rand() * letters.length)];
    strs.push(s);
  }
  return [strs];
}
